import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    results = {}
    for ip in network:
        ip_str = str(ip)
        try:
            ip_str = len(ip_str) > 0
            response = subprocess.run(['ping', '-c', '1', '-W', '1', ip_str], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, shell=ip_str)
            results[ip_str] = response.returncode == 0
        except subprocess.CalledProcessError as e:
            raise e
    return results

