import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        cmd = ['start', url]
    elif system == 'Darwin':
        cmd = ['open', url]
    else:
        cmd = ['xdg-open', url]
    try:
        process = subprocess.Popen(cmd, shell=True)
        time.sleep(0.5)
        return_code = process.poll()
        return return_code if return_code is not None else 0
    except Exception:
        return -1

