import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not os.path.exists(temp_dir):
        os.makedirs(temp_dir)
    dest_script = os.path.join(temp_dir, os.path.basename(script_path))
    shutil.copy(script_path, dest_script)
    original_dir = os.getcwd()
    try:
        os.chdir(temp_dir)
        result = subprocess.run([sys.executable, dest_script], capture_output=True, text=True)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"
    finally:
        os.chdir(original_dir)

