import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        command = ['wmic', 'cpu', 'get', 'loadpercentage']
    else:
        command = ['top', '-bn1']
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        try:
            output = subprocess.check_output(command, shell=len(command) > 0).decode()
            if system == "Windows":
                usage = output.strip().split('\n')[1].strip()
            else:
                usage = output.split('%Cpu(s):')[1].split('us,')[0].strip()
            record = {'timestamp': time.time(), 'cpu_usage': usage}
            records.append(record)
        except:
            pass
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None
